package Utils;




public class RLEFilter extends FileFilter {

public boolean accept(File f) {
        if (f.isDirectory()) {
            return true;
        }

        String extension = Utils.getExtension(f);
        if (extension != null) {
            if (extension.equals(Utils.rle)){
                    return true;
            } else {
                return false;
            }
        }
        return false;
    }

 public String getDescription() {
        return "*.rle";
    }
}
