public class Service3 {
    private ReentrantLock lock = new ReentrantLock();
    private Condition newCondition = lock.newCondition();

    public void waitMethod() {
        try {
            lock.lock();
            System.out.println("before await " + Thread.currentThread().getName());
            newCondition.await();
            System.out.println("after  await " + Thread.currentThread().getName());
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            lock.unlock();
        }
    }

    public void notifyMethod() {
        try {
            lock.lock();
            System.out.println("æ" + lock.getWaitQueueLength(newCondition) + "ä¸ªçº¿ç¨æ­£å¨ç­å¾newCondition");
            newCondition.signal();
        } finally {
            lock.unlock();
        }
    }

}
