public class BSTIterator_1 {

    public BSTIterator(TreeNode root) {
        stk = new Stack<TreeNode>();
        node = root;
    }

    public boolean hasNext() {
        if (stk.isEmpty() == true && node == null) return false;
        return true;
    }

    public int next() {
        if (stk.isEmpty() == true && node == null)  return 0;
        while (node != null) {
            stk.push(node);
            node = node.left;
        }
        int res = 0;
        node = stk.pop();
        res = node.val;
        node = node.right;
        return res;  
    }
    private Stack<TreeNode> stk;
    private TreeNode node;
}


public class BSTIterator_2 {

    public BSTIterator(TreeNode root) {
        node = root;
    }

    public boolean hasNext() {
        return node != null;
    }

    public int next() {
        if (node == null) return 0;
        int res = 0;
        while (node != null) {
            if (node.left == null) {
                res = node.val;
                node = node.right;
                return res;
            }
            TreeNode pre = node.left;
            while (pre.right != null && pre.right != node) 
                pre = pre.right;
            if (pre.right == null) {
                pre.right = node;
                node = node.left;
            } else {
                res = node.val;
                node = node.right;
                pre.right = null;
                return res;
            }
        }
        return res;
    }
    private TreeNode node;
}

