    public static final int BASIC_STRENGTH_INCREMENT = 18;public static final int EXTRA_STRENGTH_INCREMENT = 2;public static final int FOOD_DECREASE_EACH = 8;public static int getHeroStrengthIncrement(Hero hero){int level = hero.level;
        int increment = BASIC_STRENGTH_INCREMENT+level*EXTRA_STRENGTH_INCREMENT;
        if(hero.strength+increment >hero.maxStrength){
            increment = hero.maxStrength-hero.strength;
        }
        return increment;
    }
    public static int getGeneralStrengthIncrement(General general){
        int strength = general.getStrength();int increment = BASIC_STRENGTH_INCREMENT;if(strength + increment > general.maxStrength){increment = general.maxStrength - strength;
        }
        return increment;
    }
    public static int getFoodDecreaseEach(Hero hero){
        int level = hero.level;
        return FOOD_DECREASE_EACH+level;
    }
    public static int getSkillEearning(int proficiency,int basicEarning){
        return basicEarning*(proficiency);
    }

    public static int getCityDefence(CityDrawable city){
        int defend =0;
        General g = city.guardGeneral.get(0);
        float gDefend = (g.defend*0.8f+g.intelligence*0.2f)/100.0f;
        defend = (int)(city.baseDefend*city.army*(1+gDefend)) + city.warTower*100;
        return defend;
    }
    public static int getCityAttack(CityDrawable city){
        int attack = 0;General g = city.getGuardGeneral().get(0);float gAttack = (g.power*0.7f+g.agility*0.2f+g.intelligence*0.1f)/100.0f;
        attack = (int)(city.baseAttack*city.getArmy()*(1+gAttack)) + city.warTank*100;
        return (int)attack;
    }
    public static int getHeroAttack(Hero hero,General general){
        int attack = 0;float gAttack = (general.power*0.7f+general.agility*0.2f+general.intelligence*0.1f)/100.0f;attack = (int)((hero.basicAttack*hero.armyWithMe)*(1+gAttack));
        return attack;
    }
    public static int getHeroDefence(Hero hero,General general){
        int defence = 0;
        float gDefend = (general.defend*0.8f+general.intelligence*0.2f)/100.0f;defence = (int)((hero.basicDefend*hero.armyWithMe)*(1+gDefend));
        return defence;
    }
