        new Thread(){
            public void run(){
                Canvas c = SoundView.this.getHolder().lockCanvas(null);
                synchronized (SoundView.this.getHolder()) {
                    onDraw(c);
                }
                SoundView.this.getHolder().unlockCanvasAndPost(c);          
            }
        }.start();
    }

    public void surfaceDestroyed(SurfaceHolder holder) {
        }

}
