public class LoadingView extends SurfaceView implements SurfaceHolder.Callback {
    int startX = ConstantUtil.LOADING_VIEW_START_X;int startY = ConstantUtil.LOADING_VIEW_START_Y;int k = 0;public int process = 0;HDZGActivity activity;private DrawThread drawThread;Bitmap loading1;Bitmap loading2;Rect r1;Rect r2;int type;Paint paint;public LoadingView(HDZGActivity activity, int type) {super(activity);
        this.activity = activity;getHolder().addCallback(this);
        this.drawThread = new DrawThread(getHolder(), this);this.type = type;initBitmap();}

    public void initBitmap(){paint = new Paint();paint.setAntiAlias(true);
        paint.setTextSize(ConstantUtil.LOADING_VIEW_WORD_SIZE);paint.setColor(Color.WHITE);loading1 = BitmapFactory.decodeResource(getResources(), R.drawable.loading1);loading2 = BitmapFactory.decodeResource(getResources(), R.drawable.loading2);}

    public void onDraw(Canvas canvas){canvas.drawColor(Color.BLACK);
        canvas.drawBitmap(loading1, startX, startY, paint);if(process > 100){
            process = 100;
        }

        r1 = new Rect(0, 0, loading2.getWidth()*process/100, loading2.getHeight());r2 = new Rect(startX-10, startY-2, startX+loading2.getWidth()*process/100, startY+loading2.getHeight());canvas.drawBitmap(loading2, r1, r2, paint);canvas.drawText("Õ½¹úÓ¢ÐÛ´«", startX+(loading2.getWidth()/2)-20, startY, paint);
        if(k == 0){
            canvas.drawText("¼ÓÔØÖÐ", startX+(loading2.getWidth()/2)-20, startY+loading2.getHeight()+20, paint);
        }
        else if(k == 1){
            canvas.drawText("¼ÓÔØÖÐ.", startX+(loading2.getWidth()/2)-20, startY+loading2.getHeight()+20, paint);
        }
        else if(k == 2){
            canvas.drawText("¼ÓÔØÖÐ..", startX+(loading2.getWidth()/2)-20, startY+loading2.getHeight()+20, paint);
        }
        else if(k == 3){
            canvas.drawText("¼ÓÔØÖÐ...", startX+(loading1.getWidth()/2)-20, startY+loading1.getHeight()+20, paint);
        }

        k = (k+1)%4;}

    public void surfaceChanged(SurfaceHolder holder, int format, int width, int height) {
    }

    public void surfaceCreated(SurfaceHolder holder) {this.drawThread.setFlag(true);
        this.drawThread.start();}

    public void surfaceDestroyed(SurfaceHolder holder) {boolean retry = true;
        drawThread.setFlag(false);
        while (retry) {
            try {
                drawThread.join();
                retry = false;
            } 
            catch (InterruptedException e) {}
        }
    }

    class DrawThread extends Thread{private int sleepSpan = ConstantUtil.LOADING_VIEW_SLEEP_SPAN;private SurfaceHolder surfaceHolder;
        private LoadingView loadingView;
        private boolean flag = false;
        public DrawThread(SurfaceHolder surfaceHolder, LoadingView loadingView) {super.setName("==LoadingView.DrawThrea");
            this.surfaceHolder = surfaceHolder;
            this.loadingView = loadingView;
        }
        public void setFlag(boolean flag) {this.flag = flag;
        }

        public void run() {
            Canvas c;
            while (this.flag) {
                c = null;
                try {
                    c = this.surfaceHolder.lockCanvas(null);
                    synchronized (this.surfaceHolder) {
                        loadingView.onDraw(c);
                    }
                } finally {
                    if (c != null) {
                        this.surfaceHolder.unlockCanvasAndPost(c);
                    }
                }
                if(loadingView.process >= 100){loadingView.activity.myHandler.sendEmptyMessage(loadingView.type);}
                try{
                    Thread.sleep(sleepSpan);}
                catch(Exception e){
                    e.printStackTrace();
                }
            }
        }
    }
